from typing import List

def parse_music(music_string: str) -> List[int]:
    beats = {'o ': 4, 'o| ': 2, '.| ': 1}
    tokens = music_string.split(' ')
    results = []
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token in beats:
            results.append(beats[token])
            i += 1
        elif i + 1 < len(tokens) and token + ' ' + tokens[i + 1] in beats:
            results.append(beats[token + ' ' + tokens[i + 1]])
            i += 2
        else:
            i += 1
    return results
